import pytest


def rotl8(x: int, k: int) -> int:
    """Rotate the 8-bit value x left by k bits, wrapping high bits around.

    x must be in 0..255 and k in 0..7. The result is in 0..255.
    """
    return ((x << k) | (x >> (8 - k))) & 0xFF


def _rotl8_via_string(x: int, k: int) -> int:
    bits = format(x, "08b")
    return int(bits[k:] + bits[:k], 2)


def test_rotl8_zero_shift_is_identity() -> None:
    for x in (0, 1, 0x80, 0xA5, 255):
        assert rotl8(x, 0) == x


def test_rotl8_simple_shift() -> None:
    assert rotl8(0b00000001, 1) == 0b00000010
    assert rotl8(0b00010110, 3) == 0b10110000


def test_rotl8_wraps_high_bits() -> None:
    assert rotl8(0b10000000, 1) == 0b00000001
    assert rotl8(0b10000001, 1) == 0b00000011
    assert rotl8(0b11000000, 2) == 0b00000011
    assert rotl8(0b10000000, 7) == 0b01000000
    assert rotl8(0b00000001, 7) == 0b10000000


def test_rotl8_known_values() -> None:
    assert rotl8(0xA5, 4) == 0x5A
    assert rotl8(0xF0, 4) == 0x0F
    assert rotl8(0x81, 1) == 0x03


def test_rotl8_extremes() -> None:
    for k in range(8):
        assert rotl8(0, k) == 0
        assert rotl8(255, k) == 255


@pytest.mark.parametrize("k", range(8))
def test_rotl8_matches_reference_for_all_inputs(k: int) -> None:
    for x in range(256):
        assert rotl8(x, k) == _rotl8_via_string(x, k)


def test_rotl8_result_in_range() -> None:
    for x in range(256):
        for k in range(8):
            assert 0 <= rotl8(x, k) <= 255


def test_rotl8_preserves_popcount() -> None:
    for x in range(256):
        for k in range(8):
            assert rotl8(x, k).bit_count() == x.bit_count()


def test_rotl8_inverse_with_complementary_shift() -> None:
    for x in range(256):
        for k in range(1, 8):
            assert rotl8(rotl8(x, k), 8 - k) == x if k < 8 else True


def test_rotl8_composition() -> None:
    for x in range(256):
        for a in range(8):
            for b in range(8):
                assert rotl8(rotl8(x, a), b) == rotl8(x, (a + b) % 8)
